SELECT CASE WHEN country IN ('SG', 'US') THEN 'tier_1' ELSE 'other' END AS country_group, ROUND((100 * SUM(CASE WHEN city = 'Chiang Mai' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_chiang_mai, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(country))) AS country_values FROM suppliers WHERE city IN ('London', 'Berlin', 'New York') AND country IN ('US', 'DE', 'SG') GROUP BY 1 ORDER BY country_group;
